<?php
declare(strict_types=1);
namespace App\Interface\Http\Taxonomy\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Taxonomy\DTO\Request\MergeTaxonomySubjectsRequestDto;use App\Application\Taxonomy\Service\MergeTaxonomySubjectsService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class TaxonomySubjectMergeController { public function __construct(private readonly AuthService $auth,private readonly MergeTaxonomySubjectsService $merges,private readonly ApiResponseFactory $responses){} public function merge(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,string $sourceId):ResponseInterface{try{$user=$this->auth->currentUser($access);if(!in_array('ADMIN',$user->roles,true))throw new \LogicException();$payload=json_decode((string)$request->getBody(),true,512,JSON_THROW_ON_ERROR);if(!is_array($payload)||!is_string($payload['target_subject_id']??null)||!is_string($payload['reason']??null)||trim($payload['reason'])==='')throw new \InvalidArgumentException();$this->merges->merge(new MergeTaxonomySubjectsRequestDto($sourceId,$payload['target_subject_id'],$user->id,$payload['reason']));return $this->responses->success($response,['source_subject_id'=>$sourceId,'target_subject_id'=>$payload['target_subject_id']],(string)$request->getAttribute('request_id'));}catch(DomainException|\InvalidArgumentException|\JsonException|\LogicException|UnavailableUserException){return $this->responses->problem($response,'VALIDATION_FAILED','Nao foi possivel confirmar a fusao.',422,(string)$request->getAttribute('request_id'));}} }
